def rotate_marks(values, amount):
    if not values:
        return []
    shift = amount % len(values)
    return list(values[-shift:] + values[:-shift]) if shift else list(values)

def merge_distinct_runs(left, right):
    answer = []
    for value in sorted(list(left) + list(right)):
        if not answer or answer[-1] != value:
            answer.append(value)
    return answer

def parse_pairs(text):
    result = {}
    for line in text.splitlines():
        line = line.strip()
        if not line:
            continue
        key, value = line.split('=', 1)
        result[key.strip()] = value.strip()
    return result

def window_peaks(values, width):
    if width <= 0 or width > len(values):
        return []
    return [max(values[index:index + width]) for index in range(len(values) - width + 1)]

def interleave_chunks(first, second):
    result = []
    for index in range(max(len(first), len(second))):
        if index < len(first):
            result.append(first[index])
        if index < len(second):
            result.append(second[index])
    return result

def first_histogram(text):
    counts = {}
    for character in text.lower():
        if character.isalpha():
            counts[character] = counts.get(character, 0) + 1
    return counts

def clamp_interval(value, low, high):
    if low > high:
        raise ValueError('inverted interval')
    return max(low, min(high, value))

def diagonal_total(matrix):
    size = len(matrix)
    if any(len(row) != size for row in matrix):
        raise ValueError('matrix must be square')
    return sum(matrix[index][index] for index in range(size))

def transpose_rectangular(rows):
    rows = [list(row) for row in rows]
    if not rows:
        return []
    width = len(rows[0])
    if any(len(row) != width for row in rows):
        raise ValueError('matrix must be rectangular')
    return [[row[index] for row in rows] for index in range(width)]
